/* AP Biology Studio — dependency-free, same-origin client. All academic records are saved by the server. */
'use strict';
function readSavedJSON(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback;}catch{return fallback;}}
const state={page:'overview', data:null, progress:null, searchResults:null, deckUnit:'', dueOnly:false, cardIdx:0, flipped:false,
  quiz:null, qIndex:0, responses:{}, flags:new Set(), guide:null, guideMode:'concise', mode:'quiz', deckOrder:null,
  practiceUnit:'', sourceUnit:'', selectedGuide:[], selectedTutor:[], chat:[], tutorMode:'Explain it simply',
  lab:readSavedJSON('apbio-lab',{total:10,rows:[[0,0],[2,0]],notes:''})};
const $=(s,r=document)=>r.querySelector(s); const $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const e=escapeHTML;
const fmtDate=s=>{if(!s)return 'No date';const d=new Date(s.length===10?s+'T12:00:00':s);return Number.isNaN(+d)?s:d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});};
const fmtShort=s=>fmtDate(s).replace(/, \d{4}/,'');
const word=n=>n===1?'':'s';
const unitName=id=>(state.data?.units.find(u=>u.id===id)?.name||'Unassigned');
const matName=id=>(state.data?.materials.find(m=>m.id===id)?.filename||'Manual card');
let toastTimeout=null,timerInterval=null;
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='toast visible'+(error?' error':'');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>{el.className='toast';},4400);}
async function api(path,opts={}){const isForm=opts.body instanceof FormData;const res=await fetch('/api'+path,{...opts,headers:{...(isForm?{}:{'Content-Type':'application/json'}),...(opts.headers||{})}});let payload;try{payload=await res.json();}catch{payload={detail:'Unexpected server response.'};}if(!res.ok)throw Error(typeof payload.detail==='string'?payload.detail:JSON.stringify(payload.detail));return payload;}
async function refresh(){state.data=await api('/bootstrap');const due=$('#nav-due');due.textContent=state.data.stats.due;due.hidden=!state.data.stats.due;const host=$('.local-indicator span:last-child');if(host)host.textContent=state.data.public_mode?(state.data.data_durability==='temporary'?'Hosted · temporary storage':'Hosted · storage unverified'):'Local workspace';}
const btn=(action,text,cls='secondary',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const label=(text)=>`<div class="eyebrow">${e(text)}</div>`;
function pageHeader(kicker,title,desc,actions=''){return `<div class="heading-row"><div>${label(kicker)}<h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function empty(title,desc,action=''){return `<div class="empty"><div class="empty-icon">✳</div><h3>${title}</h3><p>${desc}</p>${action}</div>`;}
function unitOptions(selected='',any='All units'){return `<option value="">${e(any)}</option>`+(state.data?.units||[]).map(u=>`<option value="${u.id}" ${u.id===selected?'selected':''}>${e(u.name)}${u.status==='completed'?' · Completed':''}</option>`).join('');}
function sourcePicker({unitId='',selected=[],name='source',maxHeight=160}={}){const rows=state.data.materials.filter(m=>!unitId||m.unit_id===unitId);return `<div class="source-list" style="max-height:${maxHeight}px">${rows.length?rows.map(m=>`<label class="source-option"><input type="checkbox" name="${name}" value="${m.id}" ${selected.includes(m.id)?'checked':''}><span>${e(m.filename)} <span class="subtle">${e(unitName(m.unit_id))}</span></span></label>`).join(''):`<div class="small subtle" style="padding:10px">No files uploaded yet.</div>`}</div><small class="subtle">Leave everything unchecked to use all materials in the selected unit.</small>`;}
function markdown(s){let t=e(s||'');t=t.replace(/^### (.+)$/gm,'<h3>$1</h3>').replace(/^## (.+)$/gm,'<h2>$1</h2>').replace(/^# (.+)$/gm,'<h1>$1</h1>');t=t.replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/\*(.*?)\*/g,'<em>$1</em>');t=t.replace(/^\s*- (.+)$/gm,'<li>$1</li>').replace(/(?:<li>.*<\/li>\n?)+/g,m=>'<ul>'+m+'</ul>');t=t.split(/\n\s*\n/).map(p=>/^<(h\d|ul|li)/.test(p)?p:`<p>${p.replace(/\n/g,'<br>')}</p>`).join('');return t;}
function render(){if(!state.data)return;$('#breadcrumb').textContent=state.page.replace(/([a-z])([A-Z])/g,'$1 $2').toUpperCase();$$('.nav-item[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===state.page));document.title=({overview:'Overview',library:'Library',cards:'Flashcards',practice:'Practice',guides:'Study guides',tutor:'AI Tutor',progress:'Progress',lab:'Lab Bench',planner:'Planner',settings:'Settings'}[state.page]||'AP Biology')+' · Biology Studio';const f={overview:overview,library:library,cards:cardsPage,practice:practicePage,guides:guidesPage,tutor:tutorPage,progress:progressPage,lab:labPage,planner:plannerPage,settings:settingsPage};$('#main').innerHTML=(f[state.page]||overview)();if(state.page==='lab')updateLabResults();if(state.page==='practice'&&state.quiz?.status==='active')updateTimer();}
async function go(page){state.page=page;if(page==='progress')state.progress=await api('/progress');if(page==='tutor'&&!state.chat.length){try{state.chat=(await api('/chat/history')).messages;}catch{}}render();$('#sidebar').classList.remove('open');$('#main').focus();window.scrollTo({top:0,behavior:'instant'});}
function overview(){const s=state.data.stats;const current=state.data.units.filter(x=>x.status==='current');const due=state.data.cards.filter(c=>c.due_at<=new Date().toISOString());const past=state.data.attempts.filter(x=>x.status==='submitted').slice(0,4);return `${pageHeader('Your study headquarters','Good to see you.','Your AP Biology workspace, all in one place.',btn('jump-library','+ Upload materials','primary'))}
${state.data.data_durability==='temporary'?`<div class="storage-notice"><strong>Free hosting: work may be lost after a server restart.</strong><span>Download a full backup after important study sessions. You can restore it here later.</span>${btn('jump-settings','Back up / restore','secondary tiny')}</div>`:''}
<div class="hero"><div><span class="chip">WELCOME TO BIOLOGY STUDIO</span><h2>Make the material make sense. Then make it stick.</h2><p>Organize your teacher’s resources, practice with questions based on your notes, and build confidence topic by topic.</p>${btn('jump-practice','Start practicing ↗','primary')} ${btn('jump-cards','Review flashcards','secondary')}</div><div class="hero-art">✳</div></div>
<div class="grid stats-grid">
${metric('Study materials',s.materials,'▤','Uploaded resources')}${metric('Flashcards',s.cards,'▣',`${s.mastered} showing repeated mastery`)}${metric('Due for review',s.due,'◷',`${s.reviewed} cards reviewed`)}${metric('Average score',s.average===null?'—':s.average+'%','◉',`${s.completed} auto-graded assessments`)}</div>
<div class="grid two-col"><section class="card"><div class="card-header"><h3>📚 Your current units</h3><button class="linkish" data-action="jump-library">Manage units ↗</button></div>${current.length?current.map(u=>{const count=state.data.materials.filter(m=>m.unit_id===u.id).length;return `<div class="unit-row"><span class="unit-mark">✳</span><div class="item-main"><strong>${e(u.name)}</strong><small>${count} resource${word(count)} · Current unit</small></div>${btn('study-unit','Study ↗','secondary tiny',`data-id="${u.id}"`)}</div>`;}).join(''):empty('Your course starts here','Create your first unit and upload your notes, slides, or worksheets.',btn('jump-library','Set up my library','primary'))}</section>
<section class="card"><div class="card-header"><h3>✦ Recommended next steps</h3><span class="chip dim">PERSONALIZED</span></div><div class="tips">${due.length?`<div class="tip"><span class="tip-number">1</span><div><strong>Review ${due.length} due card${word(due.length)}</strong><small>Spaced repetition helps you retain what you learned.</small>${btn('jump-cards','Review now','ghost tiny mt16')}</div></div>`:`<div class="tip"><span class="tip-number">1</span><div><strong>${s.cards?'You’re caught up on flashcards':'Build your first deck'}</strong><small>${s.cards?'New reviews will appear here when due.':'Create flashcards from your uploaded class materials.'}</small></div></div>`}
<div class="tip"><span class="tip-number">2</span><div><strong>${s.materials?'Check your knowledge':'Upload class material'}</strong><small>${s.materials?'Try a short quiz using your class sources.':'Teacher materials are the starting point for every study tool.'}</small></div></div>
<div class="tip"><span class="tip-number">3</span><div><strong>Keep practicing across units</strong><small>Use your mistakes to decide what to review next.</small></div></div></div></section></div>
<div class="section-heading"><h2>Recent activity</h2><button class="linkish" data-action="jump-progress">View progress ↗</button></div><section class="card">${past.length?past.map(a=>`<div class="list-row"><div class="unit-mark">◉</div><div class="item-main"><strong>${e(a.title)}</strong><small>${fmtDate(a.submitted_at)} · ${e(a.mode)}</small></div><span class="chip">${a.report?.percent===null?'Needs review':a.report?.percent+'%'}</span>${btn('review-attempt','Review','secondary tiny',`data-id="${a.id}"`)}</div>`).join(''):empty('No attempts yet','Once you complete your first practice quiz, results will appear here.')}</section>`;}
function metric(name,value,icon,foot){return `<div class="card metric"><div class="metric-top"><span>${name}</span><span class="metric-icon">${icon}</span></div><div class="metric-number">${e(value)}</div><div class="metric-foot">${e(foot)}</div></div>`;}
function library(){const ms=state.data.materials;return `${pageHeader('Organize your knowledge','My Library','Add units and upload the materials you receive in class.',btn('new-unit','+ New unit','secondary'))}
<div class="grid two-col"><section class="card"><div class="card-header"><h3>Upload class materials</h3><span class="chip">SOURCE FIRST</span></div>
<form data-form="upload" id="upload-form"><div class="form-grid"><div class="field"><label for="upload-unit">Choose unit</label><select class="select" id="upload-unit" name="unit_id">${unitOptions('','No unit assigned')}</select></div><div class="field"><label for="upload-topic">Topic</label><input id="upload-topic" class="input" name="topic" placeholder="e.g., Enzyme activity" maxlength="150"></div><div class="field full"><label for="upload-lesson">Chapter / lesson</label><input id="upload-lesson" class="input" name="lesson" placeholder="e.g., Chapter 6 · How enzymes work" maxlength="150"></div></div><div class="dropzone mt16" id="dropzone" data-action="select-files"><span class="drop-icon">⇧</span><strong>Choose or drop files here</strong><small>PDF, PPTX, DOCX, TXT, CSV, JPG, PNG · 20 MB/file · charts/figures may not be read</small><input id="file-upload" name="files" class="file-input" type="file" multiple accept=".pdf,.pptx,.docx,.txt,.md,.csv,.json,.png,.jpg,.jpeg,.webp"></div><div id="chosen-files" class="small subtle mt16">No files selected</div><button type="submit" class="btn primary mt16">Upload to library</button></form></section>
<section class="card"><div class="card-header"><h3>Course units</h3><span class="chip dim">${state.data.units.length} TOTAL</span></div>${state.data.units.length?state.data.units.map(u=>`<div class="list-row"><div class="unit-mark">${u.status==='current'?'✳':'✓'}</div><div class="item-main"><strong>${e(u.name)}</strong><small>${state.data.materials.filter(x=>x.unit_id===u.id).length} files · ${e(u.status)}</small></div>${btn('toggle-unit',u.status==='current'?'Complete ✓':'Reopen','secondary tiny',`data-id="${u.id}"`)} ${btn('edit-unit','⋯','secondary tiny',`data-id="${u.id}"`)}</div>`).join(''):empty('No units yet','Create a unit to begin organizing your class.',btn('new-unit','+ Add a unit','primary'))}</section></div>
<div class="section-heading"><h2>Search inside your materials</h2></div><section class="card"><div class="row" style="align-items:stretch"><input class="input" id="fulltext-search" placeholder="Search notes, cards, and extracted files…" aria-label="Search uploaded notes"><button class="btn secondary" data-action="fulltext-search">Search</button></div><div id="fulltext-results" class="mt16 small subtle">Type a phrase to find it in saved sources.</div></section><div class="section-heading"><h2>Your materials <span class="subtle">(${ms.length})</span></h2><div class="searchbox"><input class="input" style="max-width:250px" data-role="library-search" placeholder="Filter file names…"></div></div><section class="card">${ms.length?`<div class="table-wrap"><table class="table" id="library-table"><thead><tr><th>FILE NAME</th><th>UNIT / TOPIC</th><th>TEXT EXTRACTION</th><th>ADDED</th><th></th></tr></thead><tbody>${ms.map(m=>`<tr data-title="${e((m.filename+' '+unitName(m.unit_id)+' '+m.topic).toLowerCase())}"><td><strong>${e(m.filename)}</strong><br><small class="subtle">${Math.round(m.size_bytes/1024)} KB</small></td><td>${e(unitName(m.unit_id))}<br><small class="subtle">${e(m.topic||'—')}</small></td><td>${m.text_chars?`<span class="chip">${m.text_chars.toLocaleString()} chars</span>`:`<span class="chip gold" title="${e(m.extraction_status)}">Needs text</span>`}</td><td>${fmtShort(m.created_at)}</td><td><div class="actions">${btn('view-file','View','secondary tiny',`data-id="${m.id}"`)}${btn('edit-material','Edit','secondary tiny',`data-id="${m.id}"`)}<a class="btn secondary tiny" href="/api/materials/${m.id}/file">Save</a>${btn('delete-file','×','secondary tiny',`data-id="${m.id}" title="Remove file"`)}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Your library is empty','Upload the first lesson or study packet to unlock source-grounded flashcards, practice questions, and guides.')}</section>
<p class="small subtle mt16">Files are stored by the local server. Adding them here does not automatically upload them to your ChatGPT Project or sync existing Project files.</p>`;}
function currentDeck(){const cards=state.data.cards.filter(c=>(!state.deckUnit||c.unit_id===state.deckUnit)&&(!state.dueOnly||c.due_at<=new Date().toISOString()));if(state.deckOrder){const lookup=new Map(state.deckOrder.map((id,index)=>[id,index]));cards.sort((a,b)=>(lookup.get(a.id)??999999)-(lookup.get(b.id)??999999));}return cards;}
function cardsPage(){const all=currentDeck();if(state.cardIdx>=all.length)state.cardIdx=0;const c=all[state.cardIdx];return `${pageHeader('Active recall, made simple','Flashcards','Practice recalling ideas, not just recognizing them.',`${btn('generate-cards','✳ Generate cards','primary')}${btn('new-card','+ New card','secondary')}`)}<div class="row between mb10"><div class="tabs"><button class="tab ${!state.dueOnly?'active':''}" data-action="cards-all">All cards</button><button class="tab ${state.dueOnly?'active':''}" data-action="cards-due">Due for review (${state.data.cards.filter(c=>c.due_at<=new Date().toISOString()).length})</button></div><select class="select" style="width:220px" data-role="deck-unit">${unitOptions(state.deckUnit)}</select></div>
${all.length?`<div class="deck-layout"><section><div class="deck-action-row"><span class="small subtle">Card ${state.cardIdx+1} of ${all.length}</span><div class="row">${btn('shuffle-deck','↝ Shuffle','secondary tiny')}${btn('toggle-bookmark',c.bookmarked?'★ Saved':'☆ Bookmark','secondary tiny',`data-id="${c.id}"`)}</div></div><div class="progressbar"><span style="width:${(state.cardIdx+1)/all.length*100}%"></span></div><div class="flashcard mt16" data-action="flip-card" tabindex="0" role="button" aria-label="Flip flashcard"><span class="card-label">${state.flipped?'BACK · ANSWER':'FRONT · QUESTION'}</span>${state.flipped?`<p>${e(c.back)}</p>`:`<h2>${e(c.front)}</h2>`}<span class="flip-prompt">${state.flipped?'How well did you remember?':'Tap to reveal answer ↗'}</span><span class="card-source">${e(matName(c.material_id))} · ${e(c.topic||'General')}</span></div>${state.flipped?`<div class="rating-buttons">${['again','hard','good','easy'].map((r,i)=>btn('rate-card',['Again','Hard','Good','Easy'][i],i===0?'danger':i===1?'secondary':i===2?'ghost':'primary',`data-id="${c.id}" data-rating="${r}"`)).join('')}</div>`:`<div class="row between mt16"><span class="small subtle">Think of your answer before you flip.</span>${btn('flip-card','Reveal answer ↗','primary')}</div>`}<div class="deck-action-row">${btn('previous-card','← Previous','secondary')}${btn('next-card','Next card →','secondary')}</div></section><aside class="card"><details class="deck-manager"><summary>Browse / edit deck (${all.length} cards)</summary><div class="mini-card-list">${all.slice(0,45).map(x=>`<div class="mini-card"><strong>${e(x.front)}</strong><p>${e(x.back)}</p><div class="row"><button class="linkish" data-action="edit-card" data-id="${x.id}">Edit</button><button class="linkish" data-action="delete-card" data-id="${x.id}">Delete</button><span class="chip dim">${x.reps?`${x.reps} reviews`:'New'}</span></div></div>`).join('')}</div></details></aside></div>`:empty(state.dueOnly?'All caught up!':'No cards in this deck',state.dueOnly?'Nothing is due at the moment. Choose “All cards” to study ahead.':'Create cards manually or generate them from your teacher’s notes.',btn('generate-cards','Generate flashcards','primary'))}`;}
function practicePage(){if(state.quiz)return state.quiz.status==='submitted'?renderResults():renderQuiz();const completed=state.data.attempts.slice(0,10);return `${pageHeader('Put your knowledge to the test','Practice & Tests','Targeted quizzes, timed assessments, and detailed feedback.')}
<div class="practice-box"><div class="tabs mb10"><button class="tab ${state.mode==='quiz'?'active':''}" data-action="mode-quiz">Practice quiz</button><button class="tab ${state.mode==='test'?'active':''}" data-action="mode-test">Full practice test</button></div>
<section class="card"><div class="card-header"><h3>${state.mode==='test'?'Configure a practice test':'Create a practice quiz'}</h3><span class="chip">CLASS-SOURCE QUESTIONS</span></div><form data-form="create-quiz" class="form-grid"><div class="field"><label for="quiz-unit">Unit</label><select class="select" id="quiz-unit" name="unit_id" data-role="quiz-unit">${unitOptions(state.practiceUnit)}</select></div><div class="field"><label for="quiz-count">Number of questions</label><select class="select" name="count" id="quiz-count">${[5,10,15,20,30,40].map(n=>`<option value="${n}" ${n===(state.mode==='test'?20:10)?'selected':''}>Up to ${n} questions</option>`).join('')}</select></div><div class="field"><label for="quiz-minutes">Time limit</label><select class="select" name="minutes" id="quiz-minutes">${[0,10,15,30,45,60,90].map(n=>`<option value="${n}" ${n===(state.mode==='test'?45:0)?'selected':''}>${n?n+' minutes':'Untimed'}</option>`).join('')}</select></div><div class="field"><label>Question formats</label><div class="row" style="gap:13px;padding:10px 0">${[['mcq','Multiple choice'],['multi','Multiple select'],['tf','True/false'],['fill','Fill-in'],['short','Written'],['matching','Matching']].map(([v,l])=>`<label class="checkline"><input type="checkbox" name="type" value="${v}" ${v==='mcq'||v==='tf'||v==='fill'||(state.mode==='test'&&v==='short')?'checked':''}> ${l}</label>`).join('')}</div></div><details class="full advanced-settings"><summary>More options: sources, difficulty & weak topics</summary><div class="form-grid"><div class="field"><label>Question generator</label><select class="select" name="generator"><option value="local">Local (source-extractive)</option>${state.data.ai_enabled?'<option value="ai">AI (reasoning / application)</option>':''}</select></div><div class="field"><label>Difficulty (AI generator)</label><select class="select" name="difficulty"><option value="basic">Foundation</option><option value="standard" selected>Standard</option><option value="challenge">Challenge</option></select></div><div class="field"><label>Question focus (AI generator)</label><select class="select" name="emphasis"><option value="mixed">Mixed</option><option value="knowledge">Knowledge</option><option value="understanding">Understanding</option><option value="application">Application / analysis</option></select></div><div class="field"><label class="checkline" style="padding-top:26px"><input type="checkbox" name="prioritize_mistakes" checked> Prioritize weak topics (local mode)</label></div><div class="field full"><label>Specific materials (optional)</label><div id="quiz-sources">${sourcePicker({unitId:state.practiceUnit})}</div></div></div></details><div class="full"><button class="btn primary" type="submit">${state.mode==='test'?'Begin practice test':'Generate quiz'} →</button><p class="small subtle mt16">Free generation tests definitions and direct recall from uploaded text, not advanced reasoning. Review generated questions for accuracy. Written answers require your own grading.</p></div></form></section>
<div class="section-heading"><h2>Recent assessments</h2></div><section class="card">${completed.length?completed.map(a=>`<div class="list-row"><div class="unit-mark">◉</div><div class="item-main"><strong>${e(a.title)}</strong><small>${fmtShort(a.created_at)} · ${e(a.mode)}</small></div>${a.status==='submitted'?`<span class="chip">${a.report?.percent===null?'Self-review':a.report?.percent+'%'}</span>`:`<span class="chip gold">In progress</span>`}${btn('review-attempt',a.status==='submitted'?'Results':'Resume','secondary tiny',`data-id="${a.id}"`)}</div>`).join(''):empty('Ready to start?','Choose the unit and question types above, then create your first practice session.')}</section></div>`;}
function quizAnswers(q){const current=state.responses[q.id];if(q.type==='mcq')return q.options.map((x,i)=>`<label class="answer-option"><input type="radio" name="answer" data-answer="mcq" value="${i}" ${current===i?'checked':''}><span>${e(x)}</span></label>`).join('');if(q.type==='multi')return q.options.map((x,i)=>`<label class="answer-option"><input type="checkbox" data-answer="multi" data-index="${i}" ${Array.isArray(current)&&current.includes(i)?'checked':''}><span>${e(x)}</span></label>`).join('');if(q.type==='tf')return `<div class="question-statement">${e(q.statement)}</div>`+q.options.map(x=>`<label class="answer-option"><input type="radio" name="answer" data-answer="tf" value="${e(x)}" ${current===x?'checked':''}><span>${x}</span></label>`).join('');if(q.type==='fill')return `<div class="question-statement">${e(q.statement)}</div><input class="input" data-answer="fill" value="${e(current||'')}" placeholder="Enter your answer" autocomplete="off">`;if(q.type==='short')return `<textarea class="textarea" data-answer="short" rows="6" placeholder="Write your answer. You will compare it to the source-based rubric after submission.">${e(current||'')}</textarea>`;if(q.type==='matching')return q.terms.map(term=>`<div class="field" style="margin-bottom:13px"><label>${e(term)}</label><select class="select" data-answer="matching" data-term="${e(term)}"><option value="">Choose a description…</option>${q.options.map(opt=>`<option value="${e(opt)}" ${current?.[term]===opt?'selected':''}>${e(opt)}</option>`).join('')}</select></div>`).join('');return '';}
function answered(q){const x=state.responses[q.id];return Array.isArray(x)?x.length>0:typeof x==='object'&&x!==null?Object.keys(x).length===q.terms?.length:(x!==undefined&&x!==null&&x!=='');}
function renderQuiz(){const qz=state.quiz;const q=qz.questions[state.qIndex];const done=qz.questions.filter(answered).length;return `${pageHeader('Assessment in progress',e(qz.title),`${qz.questions.length} source-based questions · Answers hidden until submission.`,btn('exit-quiz','← Back to practice','secondary'))}<div class="question-layout"><div><div class="card question-card"><div class="row between"><span class="question-count">QUESTION ${state.qIndex+1} OF ${qz.questions.length}</span><div class="row">${qz.minutes?`<span class="timer" id="timer">⏱ --:--</span>`:''}<button class="btn secondary tiny" data-action="flag-question">${state.flags.has(q.id)?'⚑ Flagged':'⚐ Flag for review'}</button></div></div><h2>${e(q.prompt)}</h2><div id="answer-area">${quizAnswers(q)}</div><div class="divider"></div><div class="row between">${btn('question-prev','← Previous','secondary',state.qIndex===0?'disabled':'')}${btn('question-next',state.qIndex===qz.questions.length-1?'Review questions':'Next question →','primary')}</div></div><p class="small subtle mt16">${q.source_name?`Source: ${e(q.source_name)} · `:''}Question type: ${e(q.type)}</p></div><aside class="card"><div class="card-header"><h3>Question map</h3><span class="chip">${done}/${qz.questions.length}</span></div><div class="progressbar mb10"><span style="width:${100*done/qz.questions.length}%"></span></div><div class="question-nav">${qz.questions.map((x,i)=>`<button data-action="question-goto" data-index="${i}" class="${i===state.qIndex?'active ':''}${answered(x)?'answered ':''}${state.flags.has(x.id)?'flagged':''}">${i+1}</button>`).join('')}</div><div class="divider"></div><div class="small subtle mb10">${state.flags.size} flagged · ${qz.questions.length-done} unanswered</div>${btn('submit-quiz','Submit answers','primary wide')}<p class="small subtle mt16">Your answers remain private until you submit.</p></aside></div>`;}
function renderResults(){const q=state.quiz,r=q.report;return `${pageHeader('Assessment complete','Your results','Answer explanations are revealed only after submission. Use missed concepts to plan review.',btn('exit-quiz','← All practice','secondary')+btn('redo-quiz','Try new questions','primary'))}<div class="grid two-even"><div class="card"><span class="kicker">SCORE ON GRADED QUESTIONS</span><div class="score-big">${r.percent===null?'—':r.percent+'%'}</div><p>${r.correct} correct of ${r.graded} graded questions · ${r.total} total. Written responses need your own review.</p><div class="progressbar"><span style="width:${r.percent||0}%"></span></div>${r.manual_needed?`<p class="small warning-text mt16">${r.manual_needed} written answer${word(r.manual_needed)} still need self-grading. Your score may change.</p>`:''}</div><div class="card"><h3>What to review next</h3>${r.missed_topics?.length?r.missed_topics.map(t=>`<div class="list-row"><span class="unit-mark">↺</span><div class="item-main"><strong>${e(t)}</strong><small>Incorrect response</small></div></div>`).join(''):`<p>No objectively missed topics recorded yet. Revisit written answers and check for misconceptions.</p>`}${btn('jump-cards','Review flashcards ↗','ghost mt16')}</div></div><div class="section-heading"><h2>Answer review</h2><span class="chip dim">Source-based explanations</span></div><div class="card">${r.details.map((d,i)=>`<div class="result-detail"><div class="row between"><strong>${i+1}. ${e(d.prompt)}</strong><span class="outcome ${d.correct===false?'bad':d.correct===null?'manual':''}">${d.correct===true?'Correct':d.correct===false?'Needs review':'Self-grade'}</span></div><p><strong>Your response:</strong> ${e(typeof d.response==='object'?JSON.stringify(d.response):d.response??'No response')}</p><p><strong>Expected:</strong> ${e(typeof d.answer==='object'?JSON.stringify(d.answer):d.answer)}</p><p class="subtle">${e(d.explanation)} · ${e(d.source_name)}</p>${btn('report-question','Report issue','secondary tiny',`data-id="${d.id}"`)}${d.type==='short'?`<div class="row">${btn('selfgrade','I got it right','ghost tiny',`data-id="${d.id}" data-value="true"`)}${btn('selfgrade','Needs more work','secondary tiny',`data-id="${d.id}" data-value="false"`)}</div>`:''}</div>`).join('')}</div>`;}
function guidesPage(){return `${pageHeader('Turn notes into understanding','Study Guides','Create source-linked review sheets from your own class material.')}
<div class="grid two-col"><section class="card"><div class="card-header"><h3>Generate a study guide</h3><span class="chip">SOURCE-GROUNDED</span></div><form data-form="guide" class="stack"><div class="form-grid"><div class="field"><label>Choose unit</label><select name="unit_id" class="select" data-role="guide-unit">${unitOptions(state.sourceUnit)}</select></div><div class="field"><label>Guide style</label><select name="mode" class="select">${[['concise','Quick review'],['detailed','Detailed guide'],['exam','Exam review sheet']].map(([a,b])=>`<option value="${a}" ${state.guideMode===a?'selected':''}>${b}</option>`).join('')}</select></div></div><div class="field"><label>Generator</label><select class="select" name="generator"><option value="local">Local (exact source extracts)</option>${state.data.ai_enabled?'<option value="ai">AI (expanded explanations)</option>':''}</select></div><div class="field"><label>Select individual sources (optional)</label><div id="guide-sources">${sourcePicker({unitId:state.sourceUnit,selected:state.selectedGuide})}</div></div><div><button class="btn primary" type="submit">✳ Build study guide</button></div></form></section><section class="card soft"><h3>How guides are built</h3><p>Without an AI API, the guide organizes definitions and exact statements found in your uploads. It won’t invent explanations missing from a source.</p><div class="tips"><div class="tip"><span class="tip-number">1</span><div><strong>Prioritize your teacher's wording</strong><small>The name of each source is shown beside concepts.</small></div></div><div class="tip"><span class="tip-number">2</span><div><strong>Use active recall</strong><small>Detailed and exam modes add recall prompts.</small></div></div><div class="tip"><span class="tip-number">3</span><div><strong>Check uploaded sources</strong><small>Extraction and OCR can occasionally misread material.</small></div></div></div></section></div><div class="section-heading"><h2>Generated guide</h2>${state.guide?`<div class="row">${btn('copy-guide','Copy text','secondary tiny')}${btn('download-guide','Download .md','secondary tiny')}</div>`:''}</div><section class="guide-preview">${state.guide?markdown(state.guide.markdown):empty('No guide opened yet','Select source materials above, or open one of your saved guides below.')}</section>
<div class="section-heading"><h2>Saved study guides <span class="subtle">(${state.data.guides?.length||0})</span></h2></div><section class="card">${state.data.guides?.length?state.data.guides.map(g=>`<div class="list-row"><span class="unit-mark">≡</span><div class="item-main"><strong>${e(g.title)}</strong><small>${e(unitName(g.unit_id))} · ${e(g.mode)} · ${fmtDate(g.created_at)} · ${g.generator==='ai'?'AI-assisted':'Source extract'}</small></div>${btn('open-guide','Open','secondary tiny',`data-id="${g.id}"`)}${btn('delete-guide','×','secondary tiny',`data-id="${g.id}" title="Delete guide"`)}</div>`).join(''):empty('Your guides will appear here','Every guide you generate is saved to your study database.')}</section>`;}
function tutorPage(){const ready=state.data.ai_enabled;return `${pageHeader('Ask better questions','Personal AI Tutor','Six learning modes, grounded in the material you upload.',`<span class="chip ${ready?'':'gold'}">${ready?'AI CONNECTION READY':'AI CONNECTION NEEDED'}</span>`)}
${!ready?`<div class="ai-offline mb10"><strong>Connect an OpenAI API key to use live tutoring.</strong><p>This application never fakes AI conversations. Your ChatGPT subscription does not automatically supply API access. Set <code>OPENAI_API_KEY</code> in your Render environment, then redeploy. API access is separately billed. All other tools work without an API key.</p></div>`:''}
<div class="grid two-col"><section class="card"><div class="card-header"><h3>Learning conversation</h3><span class="chip">${ready?'SOURCE-AWARE':'API REQUIRED'}</span></div><div class="tutor-window" id="tutor-window">${state.chat.length?state.chat.slice(-30).map(msg=>`<div class="chat-bubble ${msg.role==='user'?'user':'assistant'}">${markdown(msg.content)}</div>`).join(''):`<div class="empty"><div class="empty-icon">✦</div><h3>Learn something new.</h3><p>Ask about a concept, request a walkthrough, or explain an idea in your own words.</p></div>`}</div><form data-form="tutor"><div class="field"><label>Ask your tutor</label><textarea name="message" class="textarea" rows="3" placeholder="e.g., Why does changing pH affect enzyme activity?" ${ready?'':'disabled'} required></textarea></div><button type="submit" class="btn primary mt16" ${ready?'':'disabled'}>Send question →</button></form></section>
<section class="card"><h3>Choose a teaching style</h3><div class="field"><label>Mode</label><select class="select" data-role="tutor-mode">${['Learn a new concept','Explain it simply','Step-by-step walkthrough','Challenge me','Socratic questioning','Review my weaknesses','Teach-back mode'].map(x=>`<option ${state.tutorMode===x?'selected':''}>${e(x)}</option>`).join('')}</select></div><div class="field mt16"><label>Unit</label><select class="select" data-role="tutor-unit">${unitOptions(state.sourceUnit)}</select></div><div class="field mt16"><label>Use these sources (optional)</label><div id="tutor-sources">${sourcePicker({unitId:state.sourceUnit,selected:state.selectedTutor})}</div></div><div class="callout mt16"><strong>Trust your sources.</strong><p>The tutor cites document names and should say when a claim isn't supported by your files. Always check important exam facts.</p></div></section></div>`;}
function progressPage(){const p=state.progress||{topics:[],history:[],reviews:[]};const s=state.data.stats;const topics=p.topics.filter(x=>x.correct+x.incorrect>0);const pts=p.history.filter(x=>x.score!==null);return `${pageHeader('Every session adds up','My Progress','Measure progress over time, not just one good score.')}
<div class="grid stats-grid">${metric('Completed quizzes',s.completed,'◉','Saved attempts')}${metric('Average accuracy',s.average===null?'—':s.average+'%','↗','Graded questions')}${metric('Repeated mastery',s.mastered,'✦','Cards reviewed 3+ times')}${metric('Cards due',s.due,'◷','Time to review')}</div>
<div class="grid two-col"><section class="card"><div class="card-header"><h3>Performance by topic</h3><span class="chip">QUESTION HISTORY</span></div>${topics.length?topics.slice(0,18).map(t=>{const pct=100*t.correct/(t.correct+t.incorrect);return `<div class="topic-row"><div><strong>${e(t.topic)}</strong><small style="display:block">${t.correct+t.incorrect} graded responses</small></div><div class="chart-track"><span style="width:${pct}%"></span></div><strong>${pct.toFixed(0)}%</strong></div>`;}).join(''):`<div class="chart-blank">Take some quizzes to see topic-by-topic accuracy.</div>`}</section>
<section class="card"><h3>Score history</h3>${pts.length?`<svg viewBox="0 0 420 205" style="width:100%;margin-top:20px" aria-label="Quiz score history"><line x1="33" y1="16" x2="33" y2="170" stroke="var(--border)"/><line x1="33" y1="170" x2="404" y2="170" stroke="var(--border)"/><line x1="33" y1="95" x2="404" y2="95" stroke="var(--border)" stroke-dasharray="4 4"/><text x="0" y="20" font-size="10" fill="var(--muted)">100</text><text x="12" y="97" font-size="10" fill="var(--muted)">50</text><text x="17" y="171" font-size="10" fill="var(--muted)">0</text><polyline fill="none" stroke="var(--green)" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" points="${pts.slice(-20).map((h,i,a)=>`${35+i*(365/Math.max(1,a.length-1))},${170-h.score*1.5}`).join(' ')}"/>${pts.slice(-20).map((h,i,a)=>`<circle cx="${35+i*365/Math.max(1,a.length-1)}" cy="${170-h.score*1.5}" r="4" fill="var(--green)"><title>${e(h.name)} · ${h.score}%</title></circle>`).join('')}</svg><div class="small subtle">${pts.length} scored assessments</div>`:`<div class="chart-blank">A score trend chart will appear after your first assessment.</div>`}<div class="divider"></div><h3>Smart review priorities</h3>${topics.some(t=>t.incorrect)?topics.filter(t=>t.incorrect>0).slice(0,4).map(t=>`<div class="list-row"><span class="unit-mark">↺</span><div class="item-main"><strong>${e(t.topic)}</strong><small>${t.incorrect} missed · ${t.correct} correct</small></div></div>`).join(''):`<p>No recurring missed concepts recorded yet. Keep reviewing your cards over multiple days.</p>`}</section></div>
<div class="section-heading"><h2>Assessment record</h2></div><section class="card">${p.history.length?p.history.slice().reverse().map(a=>`<div class="list-row"><div class="item-main"><strong>${e(a.name)}</strong><small>${fmtDate(a.date)}</small></div><span class="chip ${a.score===null?'gold':''}">${a.score===null?'Needs self-review':a.score+'%'}</span>${btn('review-attempt','Open','secondary tiny',`data-id="${a.id}"`)}</div>`).join(''):empty('Nothing here yet','Your practice history is saved after quiz submission.')}</section>`;}
function labPage(){return `${pageHeader('AP Biology toolkit','Lab Bench','Work with experimental data and practice interpreting results.')}
<div class="grid two-col"><section class="card"><div class="card-header"><h3>Leaf disk ET₅₀ calculator</h3><span class="chip">PHOTOSYNTHESIS LAB</span></div><p class="small">Enter the time and cumulative number of leaf disks floating at each observation. ET₅₀ is the estimated time when half of the disks are floating, using linear interpolation between measurements.</p><div class="field" style="max-width:230px"><label>Total number of disks</label><input type="number" class="input" min="1" max="1000" step="1" data-role="lab-total" value="${e(state.lab.total)}"></div><div class="table-wrap mt16"><table class="table lab-table"><thead><tr><th>TIME (MIN)</th><th>DISKS FLOATING</th><th></th></tr></thead><tbody id="lab-rows">${state.lab.rows.map((r,i)=>`<tr><td><input class="input" type="number" data-lab="time" data-index="${i}" min="0" step="0.1" value="${e(r[0])}"></td><td><input class="input" type="number" data-lab="count" data-index="${i}" min="0" step="1" value="${e(r[1])}"></td><td><button class="btn secondary tiny" data-action="remove-lab-row" data-index="${i}">×</button></td></tr>`).join('')}</tbody></table></div><div class="row mt16">${btn('add-lab-row','+ Add reading','secondary tiny')}${btn('reset-lab','Clear readings','secondary tiny')}${btn('demo-lab','Load example','ghost tiny')}${btn('export-lab','Export CSV','ghost tiny')}</div><div class="callout mt16"><strong>Estimated ET₅₀</strong><div class="result-number" id="et50-result">—</div><p id="et50-explanation">Enter your measurements.</p></div></section><section class="card"><div class="card-header"><h3>Floating leaf disks over time</h3><span class="chip dim">LIVE GRAPH</span></div><div id="lab-graph"></div><div class="divider"></div><h3>Interpret your results</h3><p class="small">Lower ET₅₀ means disks reached 50% floating sooner. A graph alone does not establish which experimental factor caused the difference: compare independent variables and controlled conditions.</p><div class="field"><label for="lab-notes">Claim · evidence · reasoning notes</label><textarea id="lab-notes" class="textarea" rows="6" placeholder="Claim: …\nEvidence: …\nReasoning: …">${e(state.lab.notes||'')}</textarea></div>${btn('save-lab-note','Save local draft','secondary tiny mt16')}${btn('export-lab-notes','Export notes','ghost tiny mt16')}<p class="small subtle mt16">Lab readings start blank. The sample is illustrative, not an experiment result. These measurements and notes are saved only in this browser; export them for backup.</p></section></div>`;}
function labCalc(){const total=Number(state.lab.total),rows=state.lab.rows.map(([t,c])=>[t===''?NaN:Number(t),c===''?NaN:Number(c)]).sort((a,b)=>a[0]-b[0]);if(!Number.isInteger(total)||total<=0||!rows.length||rows.some(([t,c])=>t<0||!Number.isFinite(t)||!Number.isInteger(c)||c<0||c>total))return {error:'Check total disks and counts (whole numbers from 0 to total).',rows};if(rows.some((r,i)=>i&&r[1]<rows[i-1][1]))return {error:'Floating disk counts should not decrease over time.',rows};if(rows.some((r,i)=>i&&r[0]===rows[i-1][0]))return {error:'Each time point needs a unique time.',rows};const half=total/2;let et=null;for(let i=0;i<rows.length;i++){if(rows[i][1]>=half){if(i===0)et=rows[i][0];else{const [t0,c0]=rows[i-1],[t1,c1]=rows[i];et=c1===c0?t1:t0+(half-c0)*(t1-t0)/(c1-c0);}break;}}return {et,rows,total,error:null};}
function graphSvg(calc){if(calc.error||calc.rows.length<2)return `<div class="chart-blank">${e(calc.error||'Add at least two readings to show a graph.')}</div>`;const maxT=Math.max(1,...calc.rows.map(x=>x[0])),W=560,H=280,left=52,right=18,top=12,bottom=36;const X=t=>left+(t/maxT)*(W-left-right),Y=c=>top+(1-c/calc.total)*(H-top-bottom);let dots=calc.rows.map(([t,c])=>`${X(t)},${Y(c)}`).join(' ');return `<svg class="lab-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Leaf disk floating percent by time"><line x1="${left}" y1="${top}" x2="${left}" y2="${H-bottom}" stroke="var(--muted)"/><line x1="${left}" y1="${H-bottom}" x2="${W-right}" y2="${H-bottom}" stroke="var(--muted)"/>${[0,25,50,75,100].map(y=>`<line x1="${left}" x2="${W-right}" y1="${Y(calc.total*y/100)}" y2="${Y(calc.total*y/100)}" stroke="var(--border)" stroke-dasharray="3,3"/><text x="${left-7}" y="${Y(calc.total*y/100)+4}" text-anchor="end" font-size="11" fill="var(--muted)">${y}%</text>`).join('')}<polyline points="${dots}" fill="none" stroke="var(--green)" stroke-width="3" stroke-linejoin="round"/>${calc.rows.map(([t,c])=>`<circle cx="${X(t)}" cy="${Y(c)}" r="4" fill="var(--green)"><title>${t} min: ${c} / ${calc.total}</title></circle>`).join('')}${calc.et!==null?`<line x1="${X(calc.et)}" x2="${X(calc.et)}" y1="${top}" y2="${H-bottom}" stroke="var(--accent)" stroke-dasharray="5,5"/><circle cx="${X(calc.et)}" cy="${Y(calc.total/2)}" r="6" fill="var(--accent)"/>`:''}<text x="${W/2}" y="${H-7}" text-anchor="middle" font-size="12" fill="var(--muted)">Time (min)</text><text x="${left}" y="${H-21}" text-anchor="middle" font-size="10" fill="var(--muted)">0</text><text x="${W-right}" y="${H-21}" text-anchor="end" font-size="10" fill="var(--muted)">${maxT}</text></svg>`;}
function updateLabResults(){const calc=labCalc();if($('#et50-result'))$('#et50-result').textContent=calc.error?'Invalid data':calc.et===null?'Not reached':calc.et.toFixed(2)+' min';if($('#et50-explanation'))$('#et50-explanation').textContent=calc.error|| (calc.et===null?'Fewer than half the disks are floating at the final measurement.':'Linear interpolation gives the time at which half the disks float.');if($('#lab-graph'))$('#lab-graph').innerHTML=graphSvg(calc);localStorage.setItem('apbio-lab',JSON.stringify(state.lab));}
function plannerPage(){const tasks=state.data.tasks;const pending=tasks.filter(t=>!t.done);return `${pageHeader('A little every day','Study Planner','Make a plan for your upcoming quizzes, labs, and review sessions.')}
<div class="grid two-col"><section class="card"><h3>Add study task</h3><form data-form="task" class="form-grid"><div class="field full"><label>What do you need to study?</label><input class="input" name="title" placeholder="e.g., Review enzyme inhibition" required></div><div class="field"><label>Due date</label><input type="date" class="input" name="due_date"></div><div class="field"><label>Unit</label><select class="select" name="unit_id">${unitOptions('','General')}</select></div><div>${'<button class="btn primary" type="submit">+ Add task</button>'}</div></form><div class="divider"></div><div class="callout"><strong>Useful study routine</strong><p>Read a concept → explain it without notes → answer practice questions → review missed topics a few days later.</p></div></section><section class="card"><div class="card-header"><h3>Your study checklist</h3><span class="chip">${pending.length} TO DO</span></div>${tasks.length?tasks.map(t=>`<div class="plan-item ${t.done?'done':''}"><input type="checkbox" data-role="task-toggle" data-id="${t.id}" ${t.done?'checked':''} aria-label="Complete ${e(t.title)}"><div class="item-main"><strong>${e(t.title)}</strong><small>${e(unitName(t.unit_id))}</small></div><span class="plan-date">${t.due_date?fmtShort(t.due_date):'Anytime'}</span><button class="btn secondary tiny" data-action="delete-task" data-id="${t.id}">×</button></div>`).join(''):empty('Your planner is clear','Add your first study task to begin scheduling review.')}</section></div>`;}
function settingsPage(){const temporary=state.data.data_durability==='temporary';return `${pageHeader('Keep your work safe','Settings & Backup','Save a full copy of your study work, especially on free hosting.')}
${temporary?`<div class="storage-notice"><strong>Important: temporary server storage</strong><span>On Render Free, uploaded notes, saved quizzes, flashcards, and guides can disappear after restarts or redeploys. A download is the only durable copy until you set up persistent storage.</span></div>`:''}
<div class="grid two-col"><section class="card"><h3>Back up your work</h3><p>Download a ZIP containing your saved materials, cards, guides, test results, and study history. Keep the ZIP somewhere safe on your computer or cloud drive.</p><div class="stack"><a class="btn primary fit" href="/api/backup">↓ Download complete backup (.zip)</a><a class="btn secondary fit" href="/api/export">↓ Export records (.json only)</a><button class="btn secondary fit" data-action="theme">◐ Toggle light / dark mode</button></div><p class="small subtle mt16">The JSON export doesn't contain original uploaded files. The complete ZIP does. Back up after every important session on free hosting.</p><div class="divider"></div><h3>Restore a complete backup</h3><p>Use this if your hosted study data is missing. Restoring a backup <strong>replaces all current server data</strong>; it doesn't merge records. Back up current work first.</p><form data-form="restore-backup" class="stack"><div class="field"><label for="restore-file">Previously downloaded AP Bio backup ZIP</label><input id="restore-file" class="input" type="file" name="file" accept=".zip" required></div><div class="field"><label for="restore-confirm">Type RESTORE to confirm replacement</label><input id="restore-confirm" class="input" type="text" name="confirmation" autocomplete="off" placeholder="RESTORE" required></div><button class="btn danger fit" type="submit">Restore complete backup</button></form></section><section class="card"><h3>Features & connections</h3><div class="list-row"><div class="item-main"><strong>Local study tools</strong><small>Source-based cards, quizzes, guides and lab calculations; not a full AI reasoning engine</small></div><span class="chip">READY</span></div><div class="list-row"><div class="item-main"><strong>Personal AI Tutor and AI-generated questions</strong><small>Require a separately billed OPENAI_API_KEY on the host</small></div><span class="chip ${state.data.ai_enabled?'':'gold'}">${state.data.ai_enabled?'CONNECTED':'NOT CONNECTED'}</span></div><div class="list-row"><div class="item-main"><strong>Permanent server storage</strong><small>${temporary?'Not configured on this free deployment':'Check hosting plan and backups; persistence is not verified automatically'}</small></div><span class="chip ${temporary?'gold':'dim'}">${temporary?'TEMPORARY':'VERIFY'}</span></div><div class="list-row"><div class="item-main"><strong>ChatGPT Project synchronization</strong><small>Not connected; upload classroom files in My Library</small></div><span class="chip dim">NOT AVAILABLE</span></div><div class="divider"></div><p class="small">${state.data.public_mode?'Hosted mode uses a shared site-wide login. Use HTTPS and keep the password private; there is no separate student account system.':'Local mode stores data on this computer. The server still needs to be running to open the website.'}</p></section></div>`;}
function showModal(title,html){$('#modal-root').innerHTML=`<div class="modal-overlay" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${e(title)}</h2><button class="close-modal" data-action="close-modal" aria-label="Close">×</button></div>${html}</div></div>`;}
function closeModal(){$('#modal-root').innerHTML='';}
function promptCard(c){showModal(c?'Edit flashcard':'Add a flashcard',`<form data-form="save-card" data-id="${c?.id||''}" class="stack"><div class="field"><label>Front / concept</label><textarea class="textarea" name="front" rows="3" required>${e(c?.front||'')}</textarea></div><div class="field"><label>Back / explanation</label><textarea class="textarea" name="back" rows="5" required>${e(c?.back||'')}</textarea></div><div class="form-grid"><div class="field"><label>Unit</label><select class="select" name="unit_id" ${c?'disabled':''}>${unitOptions(c?.unit_id||'','No unit')}</select></div><div class="field"><label>Topic</label><input class="input" name="topic" value="${e(c?.topic||'')}" placeholder="Optional"></div></div><button class="btn primary" type="submit">Save flashcard</button></form>`);}
function promptMaterial(m){showModal('Edit file details',`<form data-form="save-material" data-id="${m.id}" class="stack"><p class="small subtle">${e(m.filename)}. The original file is not modified.</p><div class="field"><label>Unit</label><select class="select" name="unit_id">${unitOptions(m.unit_id||'','No unit')}</select></div><div class="field"><label>Topic</label><input class="input" name="topic" value="${e(m.topic||'')}"></div><div class="field"><label>Lesson</label><input class="input" name="lesson" value="${e(m.lesson||'')}"></div><button class="btn primary" type="submit">Save file details</button></form>`);}
function promptUnit(u){showModal(u?'Edit unit':'Create a unit',`<form data-form="save-unit" data-id="${u?.id||''}" class="stack"><div class="field"><label>Unit name</label><input class="input" name="name" placeholder="e.g., Unit 3 — Cellular Energetics" value="${e(u?.name||'')}" required></div><div class="field"><label>Description</label><input class="input" name="description" placeholder="Optional" value="${e(u?.description||'')}"></div><div class="field"><label>Status</label><select class="select" name="status"><option value="current" ${u?.status==='current'?'selected':''}>Current unit</option><option value="completed" ${u?.status==='completed'?'selected':''}>Completed unit</option></select></div><button class="btn primary" type="submit">Save unit</button>${u?btn('delete-unit','Delete unit (keeps unassigned files)','danger','data-id="'+u.id+'"'):''}</form>`);}
function promptGenerateCards(){if(!state.data.materials.length){toast('Upload a class document first.',true);go('library');return;}showModal('Generate flashcards',`<p class="small subtle">Create cards from definitions or actual sentences in your uploaded sources.</p><form data-form="generate-cards" class="stack"><div class="form-grid"><div class="field"><label>Unit</label><select class="select" name="unit_id" data-role="generation-unit">${unitOptions(state.deckUnit)}</select></div><div class="field"><label>Maximum cards</label><select class="select" name="count"><option>10</option><option selected>20</option><option>40</option><option>60</option></select></div></div><div class="field"><label>Generator</label><select class="select" name="generator"><option value="local">Local (extractive, no AI credits)</option>${state.data.ai_enabled?'<option value="ai">AI (OpenAI API; review accuracy)</option>':''}</select></div><div class="field"><label>Specific source files (optional)</label><div id="card-sources">${sourcePicker({unitId:state.deckUnit})}</div></div><button class="btn primary" type="submit">Generate cards</button></form>`);}
async function openQuiz(id){const q=await api('/quizzes/'+id);state.quiz=q;state.qIndex=0;state.responses=q.status==='submitted'?q.responses:readSavedJSON('apbio-q-'+q.id,{});state.flags=new Set(readSavedJSON('apbio-flags-'+q.id,[]));state.page='practice';render();}
async function clicked(ev){const target=ev.target.closest('[data-nav],[data-action]');if(!target)return;const nav=target.dataset.nav,action=target.dataset.action; if(nav){go(nav);return;}if(action==='close-modal'){if(ev.target.closest('.modal')&&ev.target!==$('.close-modal'))return;closeModal();return;}if(!action)return;
try{if(action==='theme'){const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('apbio-theme',next);return;}
if(action==='jump-settings')return go('settings');if(action==='jump-library')return go('library');if(action==='jump-cards')return go('cards');if(action==='jump-practice')return go('practice');if(action==='jump-progress')return go('progress');if(action==='jump-lab')return go('lab');
if(action==='study-unit'){state.deckUnit=target.dataset.id;return go('cards');}
if(action==='new-unit')return promptUnit();if(action==='edit-unit')return promptUnit(state.data.units.find(x=>x.id===target.dataset.id));
if(action==='toggle-unit'){const u=state.data.units.find(x=>x.id===target.dataset.id);await api('/units/'+u.id,{method:'PATCH',body:JSON.stringify({status:u.status==='current'?'completed':'current'})});await refresh();return render();}
if(action==='delete-unit'){if(!confirm('Delete this unit? Files and cards will remain, but become unassigned.'))return;await api('/units/'+target.dataset.id,{method:'DELETE'});closeModal();await refresh();return render();}
if(action==='select-files'){$('#file-upload').click();return;}
if(action==='edit-material')return promptMaterial(state.data.materials.find(x=>x.id===target.dataset.id));
if(action==='view-file'){const m=await api('/materials/'+target.dataset.id+'/text');return showModal(m.filename,`<p class="small subtle">${e(m.extraction_status)} · Text available to study tools</p><pre>${e(m.text||'No extracted text available. You can still download the original file.')}</pre><a class="btn primary" href="/api/materials/${m.id}/file">Download original</a>`);}
if(action==='fulltext-search'){const q=$('#fulltext-search').value.trim();if(q.length<2)return toast('Type at least two characters to search.',true);const r=await api('/search?q='+encodeURIComponent(q));const el=$('#fulltext-results');el.innerHTML=r.results.length?r.results.map(x=>`<div class="list-row"><span class="unit-mark">${x.kind==='card'?'▣':'▤'}</span><div class="item-main"><strong>${e(x.title)}</strong><small>${e(x.excerpt)}</small></div>${x.kind==='material'?btn('view-file','View','secondary tiny',`data-id="${x.id}"`):''}</div>`).join(''):'No matches found.';return;}
if(action==='delete-file'){if(!confirm('Remove this file? Existing flashcards remain, but the original source will no longer be available.'))return;await api('/materials/'+target.dataset.id,{method:'DELETE'});await refresh();return render();}
if(action==='cards-all'||action==='cards-due'){state.dueOnly=action==='cards-due';state.cardIdx=0;state.flipped=false;return render();}
if(action==='flip-card'){state.flipped=!state.flipped;return render();}
if(action==='next-card'||action==='previous-card'){const n=currentDeck().length;state.cardIdx=(state.cardIdx+(action==='next-card'?1:-1)+n)%n;state.flipped=false;return render();}
if(action==='shuffle-deck'){const ids=currentDeck().map(c=>c.id);for(let i=ids.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]];}state.deckOrder=ids;state.cardIdx=0;state.flipped=false;return render();}
if(action==='rate-card'){const before=currentDeck();const next=before.length>1?before[(state.cardIdx+1)%before.length].id:null;await api('/cards/'+target.dataset.id+'/review',{method:'POST',body:JSON.stringify({rating:target.dataset.rating})});state.flipped=false;await refresh();const remaining=currentDeck();state.cardIdx=next?Math.max(0,remaining.findIndex(c=>c.id===next)):0;render();return toast('Review saved. Moving to the next card.');}
if(action==='new-card')return promptCard();if(action==='edit-card')return promptCard(state.data.cards.find(x=>x.id===target.dataset.id));
if(action==='delete-card'){if(!confirm('Delete this flashcard?'))return;await api('/cards/'+target.dataset.id,{method:'DELETE'});await refresh();return render();}
if(action==='toggle-bookmark'){const c=state.data.cards.find(x=>x.id===target.dataset.id);await api('/cards/'+c.id,{method:'PATCH',body:JSON.stringify({bookmarked:!c.bookmarked})});await refresh();return render();}
if(action==='generate-cards')return promptGenerateCards();
if(action==='mode-quiz'||action==='mode-test'){state.mode=action.split('-')[1];return render();}
if(action==='question-prev'||action==='question-next'||action==='question-goto'){if(action==='question-prev')state.qIndex=Math.max(0,state.qIndex-1);else if(action==='question-next')state.qIndex=Math.min(state.quiz.questions.length-1,state.qIndex+1);else state.qIndex=Number(target.dataset.index);return render();}
if(action==='flag-question'){const id=state.quiz.questions[state.qIndex].id;if(state.flags.has(id))state.flags.delete(id);else state.flags.add(id);localStorage.setItem('apbio-flags-'+state.quiz.id,JSON.stringify([...state.flags]));return render();}
if(action==='submit-quiz'){const missing=state.quiz.questions.filter(q=>!answered(q)).length;if(!confirm(`Submit your answers? ${missing} question(s) are unanswered. Answers will be revealed after submission.`))return;return await submitQuiz();}
if(action==='exit-quiz'){state.quiz=null;state.responses={};clearInterval(timerInterval);await refresh();return render();}
if(action==='review-attempt')return await openQuiz(target.dataset.id);
if(action==='redo-quiz'){state.quiz=null;state.responses={};await refresh();return render();}
if(action==='report-question'){const message=prompt('What looks incorrect or unclear about this question?');if(!message?.trim())return;await api('/quizzes/'+state.quiz.id+'/issues',{method:'POST',body:JSON.stringify({question_id:target.dataset.id,details:message})});return toast('Issue logged in this study website (not sent to a teacher).');}
if(action==='selfgrade'){const id=state.quiz.id;const qid=target.dataset.id;const r=await api('/quizzes/'+id+'/selfgrade',{method:'POST',body:JSON.stringify({scores:{[qid]:target.dataset.value==='true'}})});state.quiz=r;await refresh();return render();}
if(action==='open-guide'){state.guide=await api('/guides/'+target.dataset.id);return render();}
if(action==='delete-guide'){if(!confirm('Delete this saved study guide?'))return;await api('/guides/'+target.dataset.id,{method:'DELETE'});if(state.guide?.id===target.dataset.id)state.guide=null;await refresh();return render();}
if(action==='copy-guide'){await navigator.clipboard.writeText(state.guide.markdown);return toast('Guide copied.');}
if(action==='download-guide')return downloadText('ap-biology-study-guide.md',state.guide.markdown,'text/markdown');
if(action==='remove-lab-row'){state.lab.rows.splice(Number(target.dataset.index),1);render();return;}
if(action==='add-lab-row'){const last=state.lab.rows.at(-1);state.lab.rows.push([last?Number(last[0])+2:0,last?Number(last[1]):0]);render();return;}
if(action==='reset-lab'){if(!confirm('Clear current lab readings and notes? Export them first if needed.'))return;state.lab={total:10,rows:[[0,0],[2,0]],notes:''};render();return;}
if(action==='demo-lab'){if(!confirm('Replace current lab values with an example?'))return;state.lab={total:10,rows:[[0,0],[2,1],[4,3],[6,6],[8,9]],notes:'EXAMPLE DATA ONLY — replace with your measurements.'};render();return;}
if(action==='export-lab')return downloadText('leaf-disk-lab.csv','Time (min),Floating disks\n'+state.lab.rows.map(r=>r.join(',')).join('\n'),'text/csv');
if(action==='save-lab-note'){state.lab.notes=$('#lab-notes').value;localStorage.setItem('apbio-lab',JSON.stringify(state.lab));return toast('Lab draft saved in this browser.');}
if(action==='export-lab-notes')return downloadText('ap-bio-lab-notes.txt',$('#lab-notes').value,'text/plain');
if(action==='delete-task'){await api('/tasks/'+target.dataset.id,{method:'DELETE'});await refresh();return render();}
}catch(err){toast(err.message||String(err),true);}}
async function submitQuiz(){const r=await api('/quizzes/'+state.quiz.id+'/submit',{method:'POST',body:JSON.stringify({responses:state.responses})});state.quiz=r;localStorage.removeItem('apbio-q-'+r.id);localStorage.removeItem('apbio-flags-'+r.id);await refresh();clearInterval(timerInterval);render();}
function downloadText(name,text,mime){const blob=new Blob([text],{type:mime+';charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function updateTimer(){clearInterval(timerInterval);if(!state.quiz?.minutes)return;const start=new Date(state.quiz.created_at).getTime();const ttl=state.quiz.minutes*60*1000;const update=()=>{if(state.page!=='practice'||state.quiz?.status!=='active'){clearInterval(timerInterval);return;}const left=Math.max(0,Math.round((start+ttl-Date.now())/1000));const t=$('#timer');if(t){t.textContent='⏱ '+Math.floor(left/60).toString().padStart(2,'0')+':'+(left%60).toString().padStart(2,'0');t.classList.toggle('low',left<60);}if(left===0){clearInterval(timerInterval);toast('Time is up; submitting your current answers.');submitQuiz().catch(err=>toast(err.message,true));}};update();timerInterval=setInterval(update,1000);}
async function submitted(ev){const form=ev.target.closest('[data-form]');if(!form)return;ev.preventDefault();const type=form.dataset.form;const fd=new FormData(form),get=n=>String(fd.get(n)||'');const button=$('button[type=submit]',form);if(button)button.disabled=true;try{
if(type==='save-unit'){const payload={name:get('name'),description:get('description'),status:get('status')};await api(form.dataset.id?'/units/'+form.dataset.id:'/units',{method:form.dataset.id?'PATCH':'POST',body:JSON.stringify(payload)});closeModal();await refresh();render();toast('Unit saved.');}
if(type==='save-material'){await api('/materials/'+form.dataset.id,{method:'PATCH',body:JSON.stringify({unit_id:get('unit_id')||null,topic:get('topic'),lesson:get('lesson')})});closeModal();await refresh();render();toast('File details saved.');}
if(type==='upload'){const f=$('#file-upload');if(!f.files.length)throw Error('Choose at least one file.');const data=new FormData();Array.from(f.files).forEach(x=>data.append('files',x));data.append('unit_id',get('unit_id'));data.append('topic',get('topic'));data.append('lesson',get('lesson'));const result=await api('/materials/upload',{method:'POST',body:data});const successes=result.results.filter(x=>x.id).length;await refresh();render();toast(`${successes} file${word(successes)} saved. ${result.results.filter(x=>x.error).map(x=>x.error).join(' ')}`);}
if(type==='save-card'){const payload={front:get('front'),back:get('back'),topic:get('topic'),unit_id:get('unit_id')};await api(form.dataset.id?'/cards/'+form.dataset.id:'/cards',{method:form.dataset.id?'PATCH':'POST',body:JSON.stringify(payload)});closeModal();await refresh();render();toast('Flashcard saved.');}
if(type==='generate-cards'){const unit_id=get('unit_id')||null;const count=Number(get('count'));const useAI=get('generator')==='ai';const selected=fd.getAll('source');const payload={unit_id,count};if(selected.length)payload.material_ids=selected;const response=await api(useAI?'/ai/cards':'/cards/generate',{method:'POST',body:JSON.stringify(payload)});closeModal();await refresh();go('cards');toast(`${response.created} cards created. Review each card for accuracy.`);}
if(type==='create-quiz'){const types=fd.getAll('type').map(String);if(!types.length)throw Error('Choose at least one question type.');const selected=fd.getAll('source');const body={mode:state.mode,unit_id:get('unit_id')||null,count:Number(get('count')),minutes:Number(get('minutes')),types,generator:get('generator'),difficulty:get('difficulty'),emphasis:get('emphasis'),prioritize_mistakes:fd.has('prioritize_mistakes')};if(selected.length)body.material_ids=selected;const result=await api('/quizzes',{method:'POST',body:JSON.stringify(body)});state.quiz=result;state.qIndex=0;state.responses={};state.flags=new Set();await refresh();render();}
if(type==='guide'){const selected=fd.getAll('source');const body={unit_id:get('unit_id')||null,mode:get('mode')};if(selected.length)body.material_ids=selected;state.guide=await api(get('generator')==='ai'?'/ai/guide':'/guides',{method:'POST',body:JSON.stringify(body)});state.guideMode=get('mode');await refresh();render();toast('Study guide saved from your source files.');}
if(type==='tutor'){const message=get('message');const tutorUnit=$('[data-role="tutor-unit"]')?.value||null;const selected=$$('#tutor-sources input:checked').map(x=>x.value);const body={message,mode:state.tutorMode,unit_id:tutorUnit};if(selected.length)body.material_ids=selected;const response=await api('/ai/chat',{method:'POST',body:JSON.stringify(body)});state.chat.push({role:'user',content:message},{role:'assistant',content:response.answer});render();$('#tutor-window')?.scrollTo({top:999999});}
if(type==='task'){await api('/tasks',{method:'POST',body:JSON.stringify({title:get('title'),due_date:get('due_date'),unit_id:get('unit_id')||null})});await refresh();render();toast('Study task added.');}
if(type==='restore-backup'){if(get('confirmation')!=='RESTORE')throw Error('Type RESTORE exactly to confirm.');if(!confirm('This will REPLACE all current study data with your backup. Continue?'))return;const result=await api('/backup/restore',{method:'POST',body:new FormData(form)});state.quiz=null;state.guide=null;state.chat=[];await refresh();render();toast(result.note||'Backup restored.');}
}catch(err){toast(err.message||String(err),true);}finally{if(button)button.disabled=false;}}
function changed(ev){const el=ev.target;const role=el.dataset.role;
if(role==='deck-unit'){state.deckUnit=el.value;state.cardIdx=0;state.flipped=false;return render();}
if(role==='quiz-unit'){state.practiceUnit=el.value;const wrap=$('#quiz-sources');if(wrap)wrap.innerHTML=sourcePicker({unitId:el.value});return;}
if(role==='generation-unit'){$('#card-sources').innerHTML=sourcePicker({unitId:el.value});return;}
if(role==='guide-unit'){state.sourceUnit=el.value;state.selectedGuide=[];$('#guide-sources').innerHTML=sourcePicker({unitId:el.value});return;}
if(role==='tutor-unit'){state.sourceUnit=el.value;state.selectedTutor=[];$('#tutor-sources').innerHTML=sourcePicker({unitId:el.value});return;}
if(role==='tutor-mode'){state.tutorMode=el.value;return;}
if(role==='task-toggle'){api('/tasks/'+el.dataset.id,{method:'PATCH',body:JSON.stringify({done:el.checked})}).then(refresh).then(render).catch(err=>toast(err.message,true));return;}
if(el.id==='file-upload'){const n=el.files?.length||0;$('#chosen-files').textContent=n?`${n} selected: ${Array.from(el.files).map(f=>f.name).join(', ')}`:'No files selected';return;}
if(el.dataset.answer)return updateResponse(el);
if(role==='lab-total'){state.lab.total=Number(el.value);return updateLabResults();}
if(el.dataset.lab){state.lab.rows[Number(el.dataset.index)][el.dataset.lab==='time'?0:1]=el.value;return updateLabResults();}
if(el.id==='lab-notes'){state.lab.notes=el.value;localStorage.setItem('apbio-lab',JSON.stringify(state.lab));}
}
function updateResponse(el){const q=state.quiz.questions[state.qIndex];if(!q)return;let answer;if(el.dataset.answer==='mcq')answer=Number(el.value);else if(el.dataset.answer==='multi'){answer=Array.isArray(state.responses[q.id])?[...state.responses[q.id]]:[];const idx=Number(el.dataset.index);if(el.checked&&!answer.includes(idx))answer.push(idx);else if(!el.checked)answer=answer.filter(x=>x!==idx);}else if(el.dataset.answer==='matching'){answer={...(state.responses[q.id]||{})};if(el.value)answer[el.dataset.term]=el.value;else delete answer[el.dataset.term];}else answer=el.value;state.responses[q.id]=answer;localStorage.setItem('apbio-q-'+state.quiz.id,JSON.stringify(state.responses));const count=state.quiz.questions.filter(answered).length;const chip=$('.question-nav')?.parentElement?.querySelector('.chip');if(chip)chip.textContent=`${count}/${state.quiz.questions.length}`;}
function keyed(ev){const el=ev.target;if(el.dataset.role==='library-search'){$$('#library-table tbody tr').forEach(tr=>tr.hidden=!tr.dataset.title.includes(el.value.toLowerCase()));}if(el.dataset.answer&&el.tagName!=='SELECT'&&el.type!=='radio')updateResponse(el);}
async function init(){document.documentElement.dataset.theme=localStorage.getItem('apbio-theme')||'light';$('#today-label').textContent=new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'});document.addEventListener('click',clicked);document.addEventListener('submit',submitted);document.addEventListener('change',changed);document.addEventListener('input',keyed);$('#menu-toggle').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));document.addEventListener('dragover',ev=>{if(ev.target.closest('#dropzone')){ev.preventDefault();ev.target.closest('#dropzone').classList.add('dragover');}});document.addEventListener('dragleave',ev=>{const zone=ev.target.closest('#dropzone');if(zone)zone.classList.remove('dragover');});document.addEventListener('drop',ev=>{const zone=ev.target.closest('#dropzone');if(!zone)return;ev.preventDefault();zone.classList.remove('dragover');const input=$('#file-upload');try{input.files=ev.dataTransfer.files;input.dispatchEvent(new Event('change',{bubbles:true}));}catch{toast('Drag-and-drop unavailable; select files instead.',true);}});document.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeModal();if((ev.key===' '||ev.key==='Enter')&&ev.target.classList.contains('flashcard')){ev.preventDefault();state.flipped=!state.flipped;render();}});
try{await refresh();render();}catch(err){$('#main').innerHTML=`<div class="card"><h2>Could not connect to the study server</h2><p>${e(err.message)}</p><p>If using the local edition, start the app with <code>./run.sh</code>. If using the hosted edition, reload the HTTPS URL or check the deployment status.</p></div>`;}}
init();
